import math


def select_channel(batch, index):
    try:
        groups = [[list(channel) for channel in group] for group in batch]
    except TypeError as exc:
        raise ValueError("batch must be three-dimensional") from exc
    if not groups or not groups[0] or not groups[0][0]:
        raise ValueError("batch dimensions must be positive")
    channel_count = len(groups[0])
    feature_count = len(groups[0][0])
    if any(len(group) != channel_count for group in groups):
        raise ValueError("inconsistent channel count")
    if any(len(channel) != feature_count for group in groups for channel in group):
        raise ValueError("inconsistent feature count")
    if any(isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value)
           for group in groups for channel in group for value in channel):
        raise ValueError("features must be finite numbers")
    if isinstance(index, bool) or not isinstance(index, int) or not 0 <= index < channel_count:
        raise ValueError("invalid index")
    return [list(group[index + 1]) for group in groups]
